import{_ as e,c as t,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"乾上乾下 乾：","description":"京氏易傳 - 乾上乾下 乾：","frontmatter":{"title":"乾上乾下 乾：","description":"京氏易傳 - 乾上乾下 乾："},"headers":[],"relativePath":"classics/jingshi/002.md","filePath":"classics/jingshi/002.md"}'),i={name:"classics/jingshi/002.md"};function r(n,a,c,_,o,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="乾上乾下-乾" tabindex="-1">乾上乾下 乾： <a class="header-anchor" href="#乾上乾下-乾" aria-label="Permalink to “乾上乾下 乾：”">​</a></h1><p>純陽用事。象配天，屬金。與坤為飛伏，居世。【壬戌土，癸酉金。】《易》雲：“用九，見群龍無首，吉”。【純陽，用九之德。】九三，三公為應，肖乾乾、夕惕之憂。</p><p>甲壬配外內二象，【乾為天地之首，分甲壬入乾位。】積算起己巳火，至戊辰土，週而復始。【吉凶之兆，積年起月，積日起時，積時起卦入本宮。】</p><p>五星從位起鎮星，【土星入西方，麗西北，居壬戌為伏位。】參宿從位起壬戌，【壬戌在世，居宗廟。】建子起潛龍，【十一月冬至，一陽生。】建巳至極，主亢位。【四月龍見於辰，陽極陰來，吉去兇生，用九吉。】</p><p>配於人事：為首，【乾為首也。】為君父。【乾象堅剛，天地之尊，故為君父。】於類：為馬，為龍。【天行運轉不息。】</p><p>降五行，頒六位。【十二辰分六位升降，以時消息吉凶。】居西北之分野，陰陽相戰之地。《易》雲：“戰於乾。”【乾為陽，西北陰，陽入陰，二氣盛必戰。】</p><p>天六位，地六氣。六象，六包（虎易注：廣西版《易佔解讀》為六色。兩字都不可解，存疑。），四象分萬物。陰陽無差，升降有等。【陰陽二十四候，律呂調矣。】人事吉凶，見乎其象，造化分乎有無。【故云：變動不居，周流六虛。】</p><p>六位純陽，陰象在中。【陽中陰，陰中陽。】陽為君，陰為臣；陽為民，陰為事。陽實陰虛，明暗之象，陰陽可知。【三五為陽，二四為陰，初上潛亢。】</p><p>水配位為褔德，【甲子水是乾之子孫。】木入金鄉居寶貝，【甲寅木是乾之財。】土臨內象為父母，【甲辰土是乾之父母。】火來四上嫌相敵，【壬午火是乾之官鬼。】金入金鄉木漸微。【壬申金同位傷木。】宗廟上建戌亥，乾本位。【戌亥乾之位。】</p><p>陽極陰生。【降入姤卦。】八卦例諸。</p>',10)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
